void SSDV3_PostProcessor::softmax(std::vector<float> &val)
{
    float max_num = -std::numeric_limits<float>::max();
    for (const auto &v: val)
        max_num = fmaxf(max_num, v);

    float sum = 0;
    for (auto &v: val) {
        v = expf(v - max_num);
        sum += v;
    }
    for (auto &v: val)
        v /= sum;
}

/*****************************************
 * Function Name : extract_detections
 * Description   : Process CPU post-processing for SSDV3 (drawing bounding boxes) and print the result on console.
 * Arguments     : floatarr = float DRP-AI output data
 *                 img = image to draw the detection result
 * Return value  : 0 if succeeded
 *                 not 0 otherwise
 ******************************************/
void SSDV3_PostProcessor::extract_detections(const std::vector<float> &inference_output_buf)
{
    std::vector<float> classes(num_classes);
    const auto         detection_count_max = inference_output_buf.size() / (4 + num_classes);

    const auto classes_start_index = 0;
    const auto boxes_start_index   = detection_count_max * num_classes;

    detections.clear();
    for (uint32_t item = 0; item < detection_count_max; item++) {

        for (uint32_t i = 0; i < classes.size(); i++) {
            classes.at(i) = inference_output_buf.at(classes_start_index + item * num_classes + i);
        }
        softmax(classes);

        const auto max_pred = std::max_element(classes.begin(), classes.end());

        if (*max_pred > TH_PROB) {
            const uint32_t pred_class = max_pred - classes.begin();
            if (pred_class == 0) {
                continue;
            }
            //            const float x=0, y=0, w=0, h=0;
            const float x = (priors[item][0] +
                             inference_output_buf.at(boxes_start_index + (item * 4) + 0) * priors[item][2] / 10) *
                            static_cast<float>(img_width);
            const float y = (priors[item][1] +
                             inference_output_buf.at(boxes_start_index + (item * 4) + 1) * priors[item][3] / 10) *
                            static_cast<float>(img_height);
            const float w =
                    (priors[item][2] * std::exp(inference_output_buf.at(boxes_start_index + (item * 4) + 2) / 5)) *
                    static_cast<float>(img_width);
            const float h =
                    (priors[item][3] * std::exp(inference_output_buf.at(boxes_start_index + (item * 4) + 3) / 5)) *
                    static_cast<float>(img_height);
            detections.emplace_back(Box{x, y, w, h}, pred_class, *max_pred);
        }
    }
}

SSDV3_PostProcessor::SSDV3_PostProcessor(const std::string &prefix) : BasePostProcessor(prefix) {}

BasePostProcessor *create_post_processor_instance(const char *prefix) { return new SSDV3_PostProcessor(prefix); }
